#' Priority Curve (RATE)
#'
#' 
#' @param data .
#' @param outcome .
#' @param treat .
#' @param control .
#' @param armTreat .
#' @param covs .
#' @param prop .
#' @param lrnLasso .
#' @param lrnRidge .
#' @param lrnEnet .
#' @param lrnRf .
#' @param lrnOls .
#' @param nsplit .
#' @param nboot .
#' @param shareMain .
#' @param level .
#' @param lambdaRule .
#' @param plot .
#' @param seed .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$fit} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$rate} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$toc} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$tocPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$fit$asDF}
#'
#' \code{as.data.frame(results$fit)}
#'
#' @export
hetrate <- function(
    data,
    outcome,
    treat,
    control = "",
    armTreat = "",
    covs,
    prop,
    lrnLasso = TRUE,
    lrnRidge = FALSE,
    lrnEnet = FALSE,
    lrnRf = FALSE,
    lrnOls = FALSE,
    nsplit = 50,
    nboot = 100,
    shareMain = 0.5,
    level = 95,
    lambdaRule = "min",
    plot = TRUE,
    seed = 1234,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("hetrate requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(treat)) treat <- jmvcore::resolveQuo(jmvcore::enquo(treat))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(prop)) prop <- jmvcore::resolveQuo(jmvcore::enquo(prop))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(treat), treat, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(prop), prop, NULL))


    options <- hetrateOptions$new(
        outcome = outcome,
        treat = treat,
        control = control,
        armTreat = armTreat,
        covs = covs,
        prop = prop,
        lrnLasso = lrnLasso,
        lrnRidge = lrnRidge,
        lrnEnet = lrnEnet,
        lrnRf = lrnRf,
        lrnOls = lrnOls,
        nsplit = nsplit,
        nboot = nboot,
        shareMain = shareMain,
        level = level,
        lambdaRule = lambdaRule,
        plot = plot,
        seed = seed,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- hetrateClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

